/**
 * GENERATED FILE PRODUCER — writes lib/geometry/__fixtures__/nose-blend-pin.json: the litres of 142 boards, the
 * 3D shape of 44 and the board-file bytes of 12 (`lib/geometry/__fixtures__/nose-blend-boards.ts`), from the app
 * BEFORE the nose rail's blend got its two sliders (quick 261127-kkw, D-02) — while the nose's rail still faded
 * from the nose 12" station to the centre station by a fixed rule and a board could store nothing about it. The
 * output is generated and must never be hand-edited.
 *
 *   npx --no-install tsx --tsconfig ./tsconfig.json scripts/extract-nose-blend-pin.ts
 *
 * run from the repository root. It is a record of the code as it stood, so it REFUSES to run once
 * `lib/geometry/rail-bands.ts` exports `noseBlendStations`: from then on the figures it would write are the new
 * code's own, and the record would prove nothing. It ran exactly once. (Nothing in package.json — `--no-install`
 * means npx can only run the tsx already in node_modules. No database is involved.)
 *
 * Each litres figure is `summarizeDesign(fields).volumeLitres.toPrecision(17)`, a string, so the test compares
 * every digit a double holds. Each surface figure is a SHA-256 over every vertex, triangle and face kind of the
 * 3D board; each file figure a SHA-256 over the bytes Export .brd File writes.
 */
import { execFileSync } from "node:child_process";
import { existsSync, writeFileSync } from "node:fs";
import path from "node:path";
import {
  noseBlendFileDigest,
  noseBlendFileLabels,
  noseBlendPinBoards,
  noseBlendSurface,
  noseBlendSurfaceDigest,
  noseBlendSurfaceLabels,
} from "@/lib/geometry/__fixtures__/nose-blend-boards";
import { summarizeDesign } from "@/lib/geometry/design";
import * as railBands from "@/lib/geometry/rail-bands";

const OUTPUT = path.resolve(process.cwd(), "lib/geometry/__fixtures__/nose-blend-pin.json");

function main() {
  if (!existsSync(path.resolve(process.cwd(), "lib/geometry/rail-bands.ts"))) {
    throw new Error("Run this from the repository root (lib/geometry/rail-bands.ts not found here).");
  }
  if ("noseBlendStations" in railBands) {
    throw new Error("the record was taken before the nose rail's blend had sliders — it is never re-run");
  }
  const boards = noseBlendPinBoards();
  const fieldsOf = (label: string) => {
    const board = boards.find((b) => b.label === label);
    if (!board) throw new Error(`no board ${label}`);
    return board.fields;
  };

  const litres: Record<string, string> = {};
  for (const board of boards) litres[board.label] = summarizeDesign(board.fields).volumeLitres.toPrecision(17);

  const fileLabels = new Set(noseBlendFileLabels());
  const surfaces: Record<string, string> = {};
  const files: Record<string, string> = {};
  for (const label of noseBlendSurfaceLabels()) {
    const surface = noseBlendSurface(fieldsOf(label));
    surfaces[label] = noseBlendSurfaceDigest(surface);
    if (fileLabels.has(label)) files[label] = noseBlendFileDigest(surface);
  }
  const orderedFiles: Record<string, string> = {};
  for (const label of noseBlendFileLabels()) orderedFiles[label] = files[label];

  const head = execFileSync("git", ["rev-parse", "HEAD"], { encoding: "utf8" }).trim();
  const date = new Date().toISOString().slice(0, 10);
  const provenance =
    "GENERATED by scripts/extract-nose-blend-pin.ts from the app before the nose rail's blend had sliders " +
    `(quick 261127-kkw; HEAD ${head}, ${date}; noseBlendPinBoards, summarizeDesign toPrecision(17), SHA-256 of ` +
    "the 3D surface and of the .brd bytes) — never hand-edit, never re-run";
  writeFileSync(OUTPUT, `${JSON.stringify({ provenance, litres, surfaces, files: orderedFiles }, null, 2)}\n`);
  for (const label of noseBlendFileLabels()) {
    console.log(`${label}: ${litres[label]} L, surface ${surfaces[label].slice(0, 12)}, file ${orderedFiles[label].slice(0, 12)}`);
  }
  console.log(
    `wrote ${path.relative(process.cwd(), OUTPUT)} (${Object.keys(litres).length} litres, ` +
      `${Object.keys(surfaces).length} surfaces, ${Object.keys(orderedFiles).length} files)`,
  );
}

try {
  main();
} catch (error: unknown) {
  console.error(error instanceof Error ? error.message : error);
  process.exitCode = 1;
}
